#!/bin/bash
S=/tmp/claude-1000/-home-steribot-projects/f0e2de92-2e5a-401c-8559-5de8ed21cbd2/scratchpad
I=/evaluation/improvement; E=/evaluation
DOCKER_NAME=botfails-cascade $S/botfails_docker.sh sh -c "python -u run_botfails_benchmark.py cascade --dataset $E/dataset/BotFails --frames $E/frames --dino-run $I/dino/best --tasks-config $I/final_tasks.json --vlm-thresholds $I/final_thresholds.json --recheck-sec 2 --release-delay 1.5 --output $I/final/cascade_test --split test --vlm-cache $I/vlm_cache.jsonl > $I/final/cascade_test.log 2>&1; python -u run_botfails_benchmark.py report --dataset $E/dataset/BotFails --dino-run $I/dino/best --cascade-run $I/final/cascade_test --output $I/final/report_heldout --split-file $I/dev_split.json --subset heldout --no-timelines 2>&1 | tail -1; python -u run_botfails_benchmark.py report --dataset $E/dataset/BotFails --dino-run $I/dino/best --cascade-run $I/final/cascade_test --output $I/final/report_dev --split-file $I/dev_split.json --subset dev --no-timelines 2>&1 | tail -1; python -u run_botfails_benchmark.py report --dataset $E/dataset/BotFails --dino-run $I/dino/best --cascade-run $I/final/cascade_test --output $I/final/report_all 2>&1 | tail -1"
echo FINISHED
